<?php require_once __DIR__.'/includes/functions.php'; if(is_logged_in()) redirect('dashboard.php'); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$password=$_POST['password']??'';
if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<6)$error='Nama, email valid, dan password minimal 6 karakter wajib diisi.';
else try{$pdo=db();$pdo->beginTransaction();$s=$pdo->prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'customer')");$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$uid=$pdo->lastInsertId();$pdo->prepare("INSERT INTO customers(user_id) VALUES(?)")->execute([$uid]);$pdo->commit();redirect('login.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Email mungkin sudah digunakan.';}}
?><!doctype html><html lang="id"><head><?php include __DIR__.'/includes/head.php'; ?></head><body><?php include __DIR__.'/includes/header.php'; ?><main class="auth"><div class="panel"><p class="eyebrow">JOIN SABLONIC</p><h1>Buat akun</h1><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><form method="post"><label>Nama<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="6" required></label><button class="btn">Daftar</button></form><p>Sudah punya akun? <a href="login.php">Login</a></p></div></main></body></html>